export type TemplateSpec = {
  templateKey: string;
  domain?: string | null;
  section: string;
  description: string;
  costCategory: string;
  unitType: string;
  notes?: string;
  salaryHint?: string;
  isAutoGenerated?: boolean;
  inputVar?: string;
  inputMonthly?: boolean;
  supervisorRatioKey?: string;
  inputThreshold?: number;
  isSalaryStub?: boolean;
  userInputCost?: string;
  costKey?: string;
  costKey2?: string;
  costKey3?: string;
  costMonthly?: boolean;
  workerRatioKey?: string;
  bufferKey?: string;
  costPctOf?: string;
  costPct?: number;
  y1UnitsZero?: boolean;
  applyY2?: boolean;
  applyY3?: boolean;
  // Parametric branch: when set, the generator evaluates this against the
  // augmented registry ({inp.*, cost keys, computed *_derived keys}) and
  // ignores costKey/costPctOf/workerRatioKey. Line units default to inputVar
  // (usually nSanitationComplexes) so a 3-complex budget = 3 × formula result.
  formula?: string;
  formulaUnitType?: string;
};

// Mark one-time capex (setup lines, but not the Y2+ maintenance line which uses
// y1UnitsZero) as Y1-only so the full setup cost isn't re-charged every year —
// matching the creche.setup / food.dp_table convention.
function oneTimeCapex(specs: TemplateSpec[]): TemplateSpec[] {
  return specs.map(t =>
    t.section === "capex" && !t.y1UnitsZero ? { ...t, applyY2: false, applyY3: false } : t
  );
}

