function withDomain(templates: TemplateSpec[], domain: string): TemplateSpec[] {
  return templates.map(t => ({ ...t, domain: t.domain === undefined ? domain : t.domain }));
}

export function getTemplatesForCity(city: string): TemplateSpec[] {
  return [
    ...withDomain(CHILDREN,             "Children"),
    ...withDomain(YOUTH,                "Youth"),
    ...withDomain(ELDERLY,              "Elderly"),
    ...withDomain(WR,                   "WelfareRights"),
    ...withDomain(crecheTemplates(city),"Creche"),
    ...withDomain(FOOD,                 "FoodDistribution"),
    ...withDomain(oneTimeCapex(RO_WATER),   "RO_Water"),
    ...withDomain(oneTimeCapex(SANITATION), "Sanitation_Complex"),
    ...withDomain(oneTimeCapex(AFTER_SCHOOL), "AfterSchoolCentre"),
    ...CROSS,
    ...ADMIN,
  ];
}
